POSTS = []

POSTS.append(dict(
 slug="how-to-get-more-customers",
 card="Seven ways contractors get more customers without buying shared leads, ranked from free and fast to slower and longer lasting.",
 title="How to Get More Customers as a Contractor",
 desc="How to get more customers as a contractor without buying shared leads: Google Business Profile, reviews, referrals, builders and your own website.",
 h1="How to get more customers *without buying leads.*",
 lede="The contractors who stay busy all year usually do the same few things: they are easy to find on Google, they have plenty of recent reviews, they ask for referrals on purpose, and they keep in touch with past customers and builders. None of it costs per lead, and all of it keeps working after the job is done.",
 ticks=["Seven ways, from fastest to longest lasting", "What homeowners check before they call", "How word of mouth and Google work together"],
 html="""<h2 id="what-customers-check">What homeowners check before they call you</h2><p>Homeowners in renovation forums describe the same routine: search Google, look at the map results, read the reviews, check photos of past work and, for bigger jobs, confirm the licence and insurance. Some say the best trades are the hardest to find because they have no website or listing at all. That is the opening: be good and easy to find.</p><h2 id="seven-ways">Seven ways to get more customers</h2><ol><li><strong>Finish your Google Business Profile.</strong> Right category, every service, service areas, hours and real photos. It is free and it is how you appear on Google Maps. Use our <a href="/guides/google-business-profile-checklist/">checklist</a>.</li><li><strong>Ask every happy customer for a Google review.</strong> Send the link by text the day the job is finished, while they are pleased. See <a href="/guides/how-to-get-google-reviews/">how to get Google reviews</a>.</li><li><strong>Knock on the neighbours' doors.</strong> When you start a job, drop a short note next door: what you are doing, how long, and your number. Neighbours see the work and often have the same job to do.</li><li><strong>Ask for referrals on purpose.</strong> “If you know anyone who needs this done, I would really appreciate the referral.” Most people are happy to, they just never think of it.</li><li><strong>Look after builders, designers and property managers.</strong> One relationship can mean steady repeat work. Turn up, finish on time, and keep them updated.</li><li><strong>Post your work.</strong> Before and after photos with a sentence about the job, on your Google profile and social media. Real work sells better than any advert.</li><li><strong>Get a website that turns searches into calls.</strong> A page for each service and area, real photos, reviews and a tap to call button. That is what lets Google send you work, and what convinces the people your customers refer. See <a href="/guides/what-a-trade-website-needs/">what a trade website needs</a>.</li></ol><h2 id="word-of-mouth">Busy on word of mouth? Do this anyway</h2><p>Plenty of trades say they never advertise because they are flat out on word of mouth, and that is a great place to be. But the same threads show the risk: one builder stops calling, a quiet winter hits, or a few regular customers move away. A strong Google presence gives you choice: pick the better jobs, raise prices when you are booked out, and keep the calendar full in slow months.</p><p>It also helps word of mouth itself. When someone recommends you, the first thing their friend does is search your name.</p><h2 id="paid">What about paid leads and ads?</h2><p>Shared lead platforms can fill gaps but get expensive fast; see <a href="/guides/is-angi-worth-it/">is Angi worth it</a>. Paid ads work best once your free presence is strong; see <a href="/guides/are-local-services-ads-worth-it/">are Local Services Ads worth it</a>.</p>""",
 checklist=["Complete your Google Business Profile", "Text a review link after every job", "Leave a note for neighbours when a job starts", "Ask every happy customer for a referral", "Check in with builders and property managers monthly", "Post before and after photos of each job", "Make sure your name brings up a proper website", "Ask every new customer how they found you"],
 faq=[("What is the fastest way to get customers as a new contractor?", "Finish your Google Business Profile, ask friends and early customers for reviews, door knock around every job, and approach builders and property managers directly."),
      ("Do contractors need a website if they get work by word of mouth?", "It helps. People who are referred to you usually search your name before calling, and a website with photos and reviews turns that search into a call."),
      ("How do I get work from builders?", "Introduce yourself with photos of your work, be reliable on the first job, and keep in touch. Builders value trades who turn up on time and communicate."),
      ("Are lead generation sites worth it?", "Sometimes, for filling gaps or when starting out. Leads are usually shared, so track your cost per won job before renewing."),
      ("How do I get more customers in a quiet month?", "Contact past customers, offer maintenance or seasonal services, and post recent work on your Google profile. Our slow season guide covers more.")],
 links=["how-to-get-google-reviews", "slow-season", "is-angi-worth-it", "/guides/local-seo-for-trades/"],
))

POSTS.append(dict(
 slug="how-to-get-google-reviews",
 card="How new contractors with one review build trust fast: the review ask, the right timing, door knocking, photos and what never to do.",
 title="How to Get Google Reviews as a New Contractor",
 desc="How to get Google reviews as a new contractor: when and how to ask, a review request text to copy, and how to build trust with only a few reviews.",
 h1="How to get Google reviews *when you are just starting out.*",
 lede="Every established trade started with no reviews. The ones who build them fastest ask every single customer, at the right moment, with a direct link, and back it up with photos of their work and a profile that looks complete. Here is exactly how.",
 ticks=["When and how to ask", "A review request text you can copy", "How to win trust with only a few reviews"],
 html="""<h2 id="the-problem">The new business problem</h2><p>A young contractor on Reddit summed it up: licensed, insured, with a website, but only one review, and a hundred calls to agents had gone nowhere. Homeowners pick the business that looks safest, and with few reviews you look like a risk, even if your work is excellent. The answer is to turn every job into proof as fast as possible.</p><h2 id="when-to-ask">When to ask for a review</h2><p>Ask on the day the job is finished, ideally while you are still on site and the customer is looking at the result. Satisfaction is highest then and drops quickly. A week later, most people have moved on.</p><h2 id="how-to-ask">How to ask (and make it easy)</h2><ol><li><strong>Get your review link.</strong> In your Google Business Profile, use the option to ask for reviews and copy the short link.</li><li><strong>Ask in person first.</strong> “Would you mind leaving a quick Google review? It really helps a small business like mine.”</li><li><strong>Send the link by text straight away.</strong> One tap and they are writing.</li><li><strong>Remind once</strong> a few days later if they have not done it.</li></ol><p>A text you can copy: “Hi Maria, thanks again for having us on the bathroom job. If you are happy with the work, a quick Google review would mean a lot to us: [link]. Cheers, Dan.”</p><h2 id="what-not-to-do">What never to do</h2><ul><li><strong>Do not buy reviews or write fake ones.</strong> Google removes them and can restrict your profile, and in some countries it can break consumer law.</li><li><strong>Do not offer discounts or gifts for reviews.</strong> Google's policies do not allow incentives.</li><li><strong>Do not only ask happy customers through a filter.</strong> Ask everyone the same way and handle problems directly.</li></ul><h2 id="build-trust">Build trust while reviews grow</h2><ul><li><strong>Photos with every job.</strong> Before and after shots with a line about the work, on your profile and website.</li><li><strong>Door knock.</strong> Neighbours who see your work in person do not need reviews to trust you.</li><li><strong>Show your licence and insurance</strong> clearly. Homeowners check them on bigger jobs.</li><li><strong>Reply to every review,</strong> good and bad. It shows you care, and future customers read the replies.</li><li><strong>Ask past customers too.</strong> Anyone you worked for before you set up your profile can still leave a review.</li></ul><h2 id="where-reviews-show">Make your reviews work harder</h2><p>Reviews on Google help you show up on Maps; reviews shown on your own website help people decide once they find you. A site that displays recent reviews next to real job photos turns a small number of reviews into a strong first impression. See <a href="/guides/what-a-trade-website-needs/">what a trade website needs</a>.</p>""",
 checklist=["Copy your Google review link", "Ask in person when each job is finished", "Text the link the same day", "Send one reminder a few days later", "Ask past customers for reviews too", "Reply to every review", "Add before and after photos to every job", "Show your licence and insurance clearly"],
 faq=[("How do I get my first Google reviews?", "Ask every customer in person when the job is finished, text them your review link the same day, and ask past customers and builders you have worked with."),
      ("Can I pay for Google reviews?", "No. Buying reviews or offering incentives breaks Google's policies, and fake reviews can be removed or lead to restrictions on your profile."),
      ("How many Google reviews does a contractor need?", "There is no magic number, but a steady flow of recent reviews matters more than a big old total. Aim for a review from most jobs."),
      ("Should I reply to bad reviews?", "Yes, calmly and briefly. Acknowledge the issue, explain what you did or will do, and offer to talk offline. Future customers judge the reply."),
      ("Can family and friends leave reviews?", "Only if they were genuine customers. Reviews must reflect a real experience with your business.")],
 links=["how-to-get-more-customers", "/guides/google-business-profile-checklist/", "/guides/local-seo-for-trades/", "/guides/what-a-trade-website-needs/"],
))

POSTS.append(dict(
 slug="slow-season",
 card="How busy trades fill winter and quiet months: maintenance offers, past customers, commercial work, Google posts and getting ready before the slump.",
 title="How to Get Work in the Slow Season as a Contractor",
 desc="How contractors get work in winter and the slow season: maintenance offers, past customer texts, commercial work, Google posts and planning ahead.",
 h1="How busy trades *fill the slow season.*",
 lede="Feast or famine is the most common complaint in trade forums after leads. The trades who stay steady plan for quiet months before they arrive: they sell maintenance, contact past customers, chase commercial and builder work, and keep their Google presence active so they are the one found when work does come up.",
 ticks=["Seven ways to fill quiet months", "A past customer text to copy", "What to set up before the slump"],
 html="""<h2 id="why">Why the slow season hits so hard</h2><p>Many trades run on word of mouth and stay flat out most of the year. Then a builder pauses a project, the weather turns, or a few regular customers go quiet, and the calendar empties at the same time as everyone else's. The fix is to build steady sources of work you can switch on when you need them.</p><h2 id="seven-ways">Seven ways to fill quiet months</h2><ol><li><strong>Sell maintenance.</strong> Servicing, inspections, cleaning, sealing, safety checks. HVAC trades sell plans; roofers sell gutter and roof checks; landscapers sell winter tidy ups.</li><li><strong>Text past customers.</strong> They already trust you. “Hi Jo, Mike here from last year's deck job. We have some space in June if you wanted that pergola done before summer.”</li><li><strong>Chase commercial and builder work.</strong> Offices, shops, schools and property managers often schedule work in quieter months.</li><li><strong>Offer the jobs people put off.</strong> Indoor work in winter: bathrooms, painting, electrical upgrades, insulation.</li><li><strong>Keep your Google profile active.</strong> Post recent jobs and seasonal offers. Fresh activity and new reviews keep you visible when people do search.</li><li><strong>Have pages for seasonal services.</strong> If your website has a page for heating repairs, storm damage or winter maintenance, Google can send you those searches when they spike. See <a href="/guides/local-seo-for-trades/">local SEO for trades</a>.</li><li><strong>Use paid options carefully.</strong> Lead platforms and ads can fill gaps, but switch them on for the quiet weeks and off when you are busy. See <a href="/guides/is-angi-worth-it/">is Angi worth it</a>.</li></ol><h2 id="before">Set it up before you need it</h2><ul><li><strong>Keep a customer list</strong> with names, numbers, jobs and dates. It is your most valuable marketing asset.</li><li><strong>Book next season early.</strong> Offer a small saving for jobs booked now and done in the quiet months.</li><li><strong>Build reviews all year</strong> so you are the obvious choice when someone searches in a slow month.</li><li><strong>Save cash in busy months</strong> to cover the gap, and raise prices when you are fully booked.</li></ul><h2 id="choice">Busy is good. Choice is better.</h2><p>A steady stream of enquiries from Google means you are never fully dependent on one builder, one platform or one season. You can pick the jobs you want, and quiet months become a chance to catch up instead of a worry. That is what your own website and Google presence are for.</p>""",
 checklist=["Write a list of past customers with dates and jobs", "Create a maintenance or servicing offer", "Text past customers before the quiet months", "Contact property managers and commercial clients", "Add pages for seasonal services to your website", "Post recent jobs on your Google profile", "Offer early booking for quiet months", "Put cash aside during busy months"],
 faq=[("How do I get more work in winter as a tradesperson?", "Offer indoor jobs and maintenance, contact past customers, chase commercial and builder work, and keep your Google profile active so you are found when people search."),
      ("What trades are busy in winter?", "Heating, plumbing, electrical, roofing repairs after storms, and indoor work like bathrooms, kitchens and painting usually hold up best."),
      ("Should I lower my prices in the slow season?", "Rather than cutting prices, many trades offer a small saving for booking ahead or bundle maintenance services. Cutting prices can be hard to undo."),
      ("How do I stop relying on one builder for work?", "Build a mix of sources: Google, reviews, past customers, several builders or property managers. No single source should be most of your work."),
      ("Do maintenance plans work for small contractors?", "Yes, especially in HVAC, plumbing, roofing, pools and landscaping. They create repeat visits and steady income through quieter months.")],
 links=["how-to-get-more-customers", "how-to-get-google-reviews", "are-local-services-ads-worth-it", "/guides/local-seo-for-trades/"],
))

POSTS.append(dict(
 slug="how-to-get-paid-on-time",
 card="Deposits, staged payments and clear terms on every quote: how contractors stop chasing late payments before the job even starts.",
 title="How to Get Paid on Time as a Contractor",
 desc="How contractors get paid on time: taking deposits, staged progress payments, payment terms on every quote, and what to do when a client pays late.",
 h1="How to get paid on time: *set it up before the job starts.*",
 lede="Late payment is one of the most common money worries for contractors, and most of it is decided before the first tool comes out. Clear terms on the quote, a deposit, staged payments tied to stages of work and fast invoicing stop most problems before they start.",
 ticks=["Deposits and staged payments", "Terms to put on every quote", "What to do when a client pays late"],
 html="""<h2 id="the-problem">How common is late payment?</h2><p>Very. A 2026 industry survey reported that around 70% of contractors regularly get paid late. For a small business, one slow payer can mean covering wages and materials out of your own pocket.</p><h2 id="deposit">Take a deposit</h2><p>A deposit does three things: it covers materials, it confirms the customer is serious, and it means you are never fully out of pocket. Ask for it before you order materials or book the job in.</p><p>Check the rules where you work. Some places limit deposits on home improvement work. California, for example, caps them for many residential jobs. A quick check with your licensing body or trade association saves trouble later.</p><h2 id="stages">Use staged payments on bigger jobs</h2><p>Split larger jobs into stages and tie each payment to a stage you can both see is finished:</p><table><thead><tr><th>Stage</th><th>Example payment</th></tr></thead><tbody><tr><td>Booking and materials</td><td>Deposit</td></tr><tr><td>Demolition and prep finished</td><td>Progress payment 1</td></tr><tr><td>Main work finished</td><td>Progress payment 2</td></tr><tr><td>Handover and final check</td><td>Final payment</td></tr></tbody></table><p>You are never far ahead of what has been paid, and the customer only pays for work they can see.</p><h2 id="terms">Terms to put on every quote</h2><ul><li>The deposit amount and when it is due.</li><li>Each stage payment and what triggers it.</li><li>When the final invoice is due (for example, within 7 days of completion).</li><li>How they can pay: bank transfer, card or payment link.</li><li>What happens with variations: agreed in writing, priced before the work is done.</li><li>The expiry date of the quote.</li></ul><p>Customers who agree to clear terms before the job starts rarely argue about them at the end.</p><h2 id="invoice-fast">Invoice the same day</h2><p>Send the invoice the day each stage finishes, while the customer is happy with the work. Use invoicing software or a payment link so paying takes one tap. The longer you wait to invoice, the longer you wait to be paid.</p><h2 id="late">When a client pays late</h2><ol><li><strong>Friendly reminder</strong> the day after it is due: “Just a reminder the invoice for your fence is due. Here is the link to pay.”</li><li><strong>Phone call</strong> a few days later. Often there is a simple reason you can sort out.</li><li><strong>Formal letter</strong> with a clear deadline, referring to the terms they agreed.</li><li><strong>Get advice.</strong> If it is still unpaid, speak to your trade association or a lawyer about your options where you work.</li></ol><h2 id="good-customers">Attract better customers in the first place</h2><p>Customers who find you because of your reviews and your work, rather than the cheapest price on a lead platform, are usually easier to work with and quicker to pay. A professional website with clear processes sets expectations before the first call. See <a href="/guides/what-a-trade-website-needs/">what a trade website needs</a>.</p><p><em>This guide is general information, not legal or financial advice.</em></p>""",
 checklist=["Write standard payment terms for every quote", "Take a deposit before ordering materials", "Check local rules on deposit limits", "Split big jobs into staged payments", "Agree variations in writing before doing them", "Invoice the same day each stage is finished", "Offer a one tap payment link", "Follow up late payments within a day"],
 faq=[("How much deposit should a contractor take?", "It depends on the job and local rules. Many trades take enough to cover materials. Some places cap deposits on home improvement work, so check where you work."),
      ("What are progress payments?", "Payments tied to stages of a job, such as preparation, main work and completion, so the customer pays as work is finished."),
      ("How do I ask a customer for payment politely?", "Send a short reminder with a payment link the day after it is due, then call. Most late payers respond to a friendly, direct nudge."),
      ("Should I start work without a deposit?", "It is risky, especially when you buy materials. A deposit confirms the customer is serious and protects your cash."),
      ("What should payment terms on a quote include?", "The deposit, each stage payment and its trigger, when the final invoice is due, how to pay, how variations are handled and when the quote expires.")],
 links=["customer-ghosted-after-quote", "should-you-charge-for-quotes", "how-to-get-more-customers", "/guides/what-a-trade-website-needs/"],
))
